const upsertTrackedVideo = `-- name: UpsertTrackedVideo :one
INSERT INTO analytics_tracked_videos (
    tenant_id, channel_id, youtube_video_id, source, title, duration_seconds, published_at, added_by
) VALUES (
    $1, $2, $3, $4, $5, $6, $7, $8
)
ON CONFLICT (tenant_id, youtube_video_id) DO UPDATE SET
    source = CASE WHEN analytics_tracked_videos.source = 'publication' THEN 'publication' ELSE EXCLUDED.source END,
    title = CASE WHEN EXCLUDED.title <> '' THEN EXCLUDED.title ELSE analytics_tracked_videos.title END,
    duration_seconds = COALESCE(EXCLUDED.duration_seconds, analytics_tracked_videos.duration_seconds),
    published_at = COALESCE(EXCLUDED.published_at, analytics_tracked_videos.published_at)
WHERE analytics_tracked_videos.channel_id = EXCLUDED.channel_id
RETURNING tenant_id, channel_id, youtube_video_id, source, title, duration_seconds, published_at, added_by, created_at
`

type UpsertTrackedVideoParams struct {
	TenantID        pgtype.UUID        `json:"tenant_id"`
	ChannelID       pgtype.UUID        `json:"channel_id"`
	YoutubeVideoID  string             `json:"youtube_video_id"`
	Source          string             `json:"source"`
	Title           string             `json:"title"`
	DurationSeconds pgtype.Int4        `json:"duration_seconds"`
	PublishedAt     pgtype.Timestamptz `json:"published_at"`
	AddedBy         pgtype.UUID        `json:"added_by"`
}

// A video already tracked keeps its source when it came from a
// publication (a manual add never downgrades it) and gains metadata.
func (q *Queries) UpsertTrackedVideo(ctx context.Context, arg UpsertTrackedVideoParams) (AnalyticsTrackedVideo, error) {
	row := q.db.QueryRow(ctx, upsertTrackedVideo,
		arg.TenantID,
		arg.ChannelID,
		arg.YoutubeVideoID,
		arg.Source,
		arg.Title,
		arg.DurationSeconds,
		arg.PublishedAt,
		arg.AddedBy,
	)
	var i AnalyticsTrackedVideo
	err := row.Scan(
		&i.TenantID,
		&i.ChannelID,
		&i.YoutubeVideoID,
		&i.Source,
		&i.Title,
		&i.DurationSeconds,
		&i.PublishedAt,
		&i.AddedBy,
		&i.CreatedAt,
	)
	return i, err
}

const upsertVideoAnalyticsDaily = `-- name: UpsertVideoAnalyticsDaily :exec
INSERT INTO video_metrics_daily AS m (
    tenant_id, channel_id, youtube_video_id, date, views, estimated_minutes_watched,
    average_view_duration, average_view_percentage, subscribers_gained, unavailable, analytics_synced_at
)
SELECT $1, $2, r.video, r.date, r.views, r.minutes,
       r.avg_duration, r.avg_percentage, r.subs_gained, COALESCE(r.unavailable, '{}'), now()
FROM jsonb_to_recordset($3::jsonb) AS r(
    video text, date date, views bigint, minutes double precision,
    avg_duration double precision, avg_percentage double precision, subs_gained bigint, unavailable jsonb
)
ON CONFLICT (tenant_id, youtube_video_id, date) DO UPDATE SET
    channel_id = EXCLUDED.channel_id,
    views = EXCLUDED.views,
    estimated_minutes_watched = EXCLUDED.estimated_minutes_watched,
    average_view_duration = EXCLUDED.average_view_duration,
    average_view_percentage = EXCLUDED.average_view_percentage,
    subscribers_gained = EXCLUDED.subscribers_gained,
    unavailable = (m.unavailable - $4::text[]) || EXCLUDED.unavailable,
    analytics_synced_at = now()
WHERE m.tenant_id = $1
`

type UpsertVideoAnalyticsDailyParams struct {
	TenantID  pgtype.UUID `json:"tenant_id"`
	ChannelID pgtype.UUID `json:"channel_id"`
	Rows      []byte      `json:"rows"`
	ClearKeys []string    `json:"clear_keys"`
}

// rows: [{"video":..,"date":"YYYY-MM-DD","views":..,"minutes":..,
// "avg_duration":..,"avg_percentage":..,"subs_gained":..,"unavailable":{..}}].
// Only the Analytics API columns are written; the keys listed in
// clear_keys are dropped from unavailable before the row's own reasons
// are merged in, so reach-report reasons are left alone.
func (q *Queries) UpsertVideoAnalyticsDaily(ctx context.Context, arg UpsertVideoAnalyticsDailyParams) error {
	_, err := q.db.Exec(ctx, upsertVideoAnalyticsDaily,
		arg.TenantID,
		arg.ChannelID,
		arg.Rows,
		arg.ClearKeys,
	)
	return err
}

const upsertVideoReachDaily = `-- name: UpsertVideoReachDaily :exec
INSERT INTO video_metrics_daily AS m (
    tenant_id, channel_id, youtube_video_id, date, impressions, ctr, reach_synced_at
)
SELECT $1, $2, r.video, r.date, r.impressions, r.ctr, now()
FROM jsonb_to_recordset($3::jsonb) AS r(video text, date date, impressions bigint, ctr double precision)
ON CONFLICT (tenant_id, youtube_video_id, date) DO UPDATE SET
    impressions = EXCLUDED.impressions,
    ctr = EXCLUDED.ctr,
    unavailable = m.unavailable - 'impressions' - 'ctr',
    reach_synced_at = now()
WHERE m.tenant_id = $1
`

type UpsertVideoReachDailyParams struct {
	TenantID  pgtype.UUID `json:"tenant_id"`
	ChannelID pgtype.UUID `json:"channel_id"`
	Rows      []byte      `json:"rows"`
}

// rows: [{"video":..,"date":"YYYY-MM-DD","impressions":..,"ctr":..}], one
// per video and day, already aggregated across the report's other
// dimensions. Values replace (never add to) what is stored, so a report
// re-delivered or a backfill for the same days cannot double count.
func (q *Queries) UpsertVideoReachDaily(ctx context.Context, arg UpsertVideoReachDailyParams) error {
	_, err := q.db.Exec(ctx, upsertVideoReachDaily, arg.TenantID, arg.ChannelID, arg.Rows)
	return err
}

const videoDailySeries = `-- name: VideoDailySeries :many
SELECT date, views, estimated_minutes_watched, average_view_duration, average_view_percentage,
       subscribers_gained, impressions, ctr, unavailable
FROM video_metrics_daily
WHERE tenant_id = $1 AND youtube_video_id = $2
  AND date >= $3 AND date <= $4
ORDER BY date
`

type VideoDailySeriesParams struct {
	TenantID       pgtype.UUID `json:"tenant_id"`
	YoutubeVideoID string      `json:"youtube_video_id"`
	FromDate       pgtype.Date `json:"from_date"`
	ToDate         pgtype.Date `json:"to_date"`
}

type VideoDailySeriesRow struct {
	Date                    pgtype.Date   `json:"date"`
	Views                   pgtype.Int8   `json:"views"`
	EstimatedMinutesWatched pgtype.Float8 `json:"estimated_minutes_watched"`
	AverageViewDuration     pgtype.Float8 `json:"average_view_duration"`
	AverageViewPercentage   pgtype.Float8 `json:"average_view_percentage"`
	SubscribersGained       pgtype.Int8   `json:"subscribers_gained"`
	Impressions             pgtype.Int8   `json:"impressions"`
	Ctr                     pgtype.Float8 `json:"ctr"`
	Unavailable             []byte        `json:"unavailable"`
}

func (q *Queries) VideoDailySeries(ctx context.Context, arg VideoDailySeriesParams) ([]VideoDailySeriesRow, error) {
	rows, err := q.db.Query(ctx, videoDailySeries,
		arg.TenantID,
		arg.YoutubeVideoID,
		arg.FromDate,
		arg.ToDate,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []VideoDailySeriesRow
	for rows.Next() {
		var i VideoDailySeriesRow
		if err := rows.Scan(
			&i.Date,
			&i.Views,
			&i.EstimatedMinutesWatched,
			&i.AverageViewDuration,
			&i.AverageViewPercentage,
			&i.SubscribersGained,
			&i.Impressions,
			&i.Ctr,
			&i.Unavailable,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

